def clean_numeric_value(value):
    """
    Clean a single numeric value by:
    1. Converting to string
    2. Replacing comma with period for decimal point
    3. Handling scientific notation
    4. Converting to float

    Returns: cleaned float value or None if invalid
    """
    if pd.isna(value) or value == '':
        return None

    # Convert to string and strip whitespace
    value_str = str(value).strip()

    # Replace comma decimal separator with period
    value_str = value_str.replace(',', '.')

    try:
        # Convert to float (handles scientific notation automatically)
        cleaned = float(value_str)
        return cleaned
    except (ValueError, TypeError):
        return None


def harmonize_units(value, feature_name):
    """
    Check if value is outside expected US conventional range and convert if needed.

    Args:
        value: numeric value (already cleaned)
        feature_name: name of the lab feature

    Returns: harmonized value in US conventional units
    """
    if value is None or pd.isna(value):
        return None

    if feature_name not in FEATURE_RANGES_AND_CONVERSIONS:
        return value

    config = FEATURE_RANGES_AND_CONVERSIONS[feature_name]
    us_min, us_max = config['us_range']
    conversion_factor = config['si_to_us']
    si_threshold = config['si_threshold']

    # Special handling for features with different unit systems
    if si_threshold is not None:
        # Check if value needs conversion based on threshold logic

        # For creatinine: if > 50, likely in µmol/L
        if feature_name == 'Serum_Creatinine' and value > si_threshold:
            return value * conversion_factor

        # For BUN: if < 100, might be in mmol/L
        elif feature_name == 'BUN' and value < 50:
            return value * conversion_factor

        # For hemoglobin: if > 25, likely in g/L
        elif feature_name == 'Hemoglobin' and value > si_threshold:
            return value * conversion_factor

        # For calcium: if < 4, likely in mmol/L
        elif feature_name == 'Serum_Calcium' and value < si_threshold:
            return value * conversion_factor

        # For magnesium: if < 3, likely in mmol/L
        elif feature_name == 'Magnesium' and value < 3:
            return value * conversion_factor

        # For cholesterol markers: if value is very low, likely in mmol/L
        elif feature_name in ['Total_Cholesterol', 'LDL_Cholesterol', 'HDL_Cholesterol',
                              'Triglycerides', 'Non_HDL_Cholesterol'] and value < si_threshold:
            return value * conversion_factor

        # For glucose: if < 50, likely in mmol/L
        elif feature_name == 'Glucose' and value < si_threshold:
            return value * conversion_factor

        # For uric acid: if > 100, likely in µmol/L
        elif feature_name == 'Uric_Acid' and value > si_threshold:
            return value * conversion_factor

        # For bilirubin: if > 50, likely in µmol/L
        elif feature_name in ['Total_Bilirubin', 'Direct_Bilirubin'] and value > si_threshold:
            return value * conversion_factor

        # For albumin/protein: if > threshold, likely in g/L
        elif feature_name in ['Albumin_Serum', 'Total_Protein'] and value > si_threshold:
            return value * conversion_factor

        # For Vitamin D: if > threshold, likely in different unit
        elif feature_name in ['Vitamin_D_25OH', 'Vitamin_D_1_25OH'] and value > si_threshold:
            return value * conversion_factor

        # For thyroid hormones
        elif feature_name == 'Free_T4' and value > si_threshold:
            return value * conversion_factor

        elif feature_name == 'Free_T3' and value > si_threshold:
            return value * conversion_factor

        # For pCO2 and pO2: special handling
        elif feature_name == 'pCO2_Arterial' and value < 15:
            return value * conversion_factor
        elif feature_name == 'pO2_Arterial' and value < 100:
            # Check if really in kPa (typically < 20 kPa = ~150 mmHg)
            if value < 20:
                return value * conversion_factor

    return value


def process_lab_data(input_file, output_file):
    """
    Main processing function to harmonize clinical lab data.
    """
    print("Reading input file...")
    df = pd.read_csv(input_file)
    print(f"Loaded {len(df)} patient records with {len(df.columns)} columns")

    # Get all feature columns (everything except patient_id)
    feature_cols = [col for col in df.columns if col != 'patient_id']

    print("\nStep 1: Cleaning numeric values (handling scientific notation and decimal formats)...")
    # Clean all numeric values
    for col in feature_cols:
        df[col] = df[col].apply(clean_numeric_value)

    print(f"Records before removing missing values: {len(df)}")

    print("\nStep 2: Removing rows with missing values...")
    # Remove rows with any missing values in feature columns
    df_clean = df.dropna(subset=feature_cols)
    print(f"Records after removing missing values: {len(df_clean)}")
    print(f"Removed {len(df) - len(df_clean)} incomplete records")

    print("\nStep 3: Harmonizing units to US conventional standards...")
    # Apply unit harmonization to each feature
    for col in feature_cols:
        df_clean[col] = df_clean[col].apply(lambda x: harmonize_units(x, col))

    print("\nStep 4: Rounding all values to 2 decimal places...")
    # Round all numeric columns to 2 decimal places
    for col in feature_cols:
        df_clean[col] = df_clean[col].apply(lambda x: round(x, 2) if pd.notna(x) else x)

    # Format all values to exactly 2 decimal places (X.XX format)
    for col in feature_cols:
        df_clean[col] = df_clean[col].apply(lambda x: f"{x:.2f}" if pd.notna(x) else x)

    print("\nStep 5: Saving harmonized data...")
    # Save to CSV
    df_clean.to_csv(output_file, index=False)
    print(f"Saved {len(df_clean)} harmonized records to {output_file}")

    # Print summary statistics
    print("\n" + "="*80)
    print("HARMONIZATION SUMMARY")
    print("="*80)
    print(f"Input records: {len(df)}")
    print(f"Output records: {len(df_clean)}")
    print(f"Records removed: {len(df) - len(df_clean)}")
    print(f"Features harmonized: {len(feature_cols)}")
    print("="*80)

    return df_clean


if __name__ == "__main__":
    input_file = "/root/environment/data/ckd_lab_data.csv"
    output_file = "/root/ckd_lab_data_harmonized.csv"

    result = process_lab_data(input_file, output_file)

    print("\nSample of harmonized data (first 3 rows, first 10 columns):")
    print(result.iloc[:3, :10])
    print("\nHarmonization complete!")

